'use client';

import type { ComponentType } from 'react';
import { createImageEffect } from './image-effects/create-image-effect.js';
import definition from './image-effects/definitions/liquid-glass-grid.js';
import type { ImageEffectProps } from './image-effects/props';

export const LiquidGlassGrid: ComponentType<ImageEffectProps & { videos?: readonly (string | null)[]; labels?: readonly string[] }> = createImageEffect('LiquidGlassGrid', definition);

import { createGlassSurface } from '../glass-surface.js';

export default {
  background:"#030313", count: 63, pan: true, glass: true, surface: () => createGlassSurface(9, 7),
  layout({ slot, phase, travel, verticalPhase, verticalBase }) {
    const row = Math.floor(slot / 9);
    const worldRow = row + verticalBase;
    const longitude = ((slot % 9) - 4 - phase + ((worldRow % 2 + 2) % 2) / 2) * .127;
    const latitude = (row - 3 - verticalPhase) * .069;
    const radius = 3.15;
    return {
      w: .385, h: .205, textureIndex: worldRow * 9 + slot % 9 + Math.floor(travel),
      x: radius * Math.cos(latitude) * Math.sin(longitude),
      y: radius * Math.sin(latitude),
      z: radius * (Math.cos(latitude) * Math.cos(longitude) - 1),
      ry: longitude, rx: -latitude,
    };
  },
  vertex: `
    float weight = sin(uv.x * 3.14159) * sin(uv.y * 3.14159);
    float bend = dot(uv - .5, flex);
    p.z += weight * bend * .25;
    p.xy -= flex * weight * .035;
  `,
  functions: `
    float tileDistance(vec2 p, vec2 extent, float radius) {
      vec2 corner = abs(p) - extent + radius;
      return length(max(corner, 0.)) + min(max(corner.x, corner.y), 0.) - radius;
    }
  `,
  fragment: `
    vec2 extent = vec2(ratio, 1.) * .5;
    vec2 pos = (uv - .5) * 2. * extent;
    float d = tileDistance(pos, extent, .17);
    if (d > 0.) discard;
    vec2 normal = normalize(vec2(
      tileDistance(pos + vec2(.001, 0.), extent, .17) - d,
      tileDistance(pos + vec2(0., .001), extent, .17) - d
    ) + .00001);
    // The cross-section is a rounded bevel: a flat central window and
    // a rapidly changing normal within the last 9% of the short edge.
    float rim = clamp(1. + d / .09, 0., 1.);
    float nz = sqrt(max(.001,1. - rim*rim));
    vec3 N = normalize(vec3(normal*rim,nz));
    vec3 viewDir = normalize(vec3((uv-.5)*.16,1.));
    vec3 ray = refract(-viewDir,N,1./1.48);
    vec2 bend = ray.xy * (.13 / max(.12,abs(ray.z))) / vec2(ratio,1.);
    vec2 base = (uv-.5)*.92+.5;
    color = sampleA(base+bend);
    color.r = sampleA(base + bend*1.06).r;
    color.b = sampleA(base + bend*.94).b;
    vec3 refl = reflect(-viewDir,N);
    float fresnel = .045+.955*pow(1.-max(0.,dot(N,viewDir)),5.);
    float panel = smoothstep(.82,.97,dot(refl,normalize(vec3(-.65,.5,.57))));
    color.rgb = mix(color.rgb,vec3(.59,.65,.79)+panel*.55,fresnel*.72);
    color.rgb += panel*rim*.65 + .075*rim;
    vec4 lettering = texture2D(labelMap,uv + bend*.22);
    color.rgb = mix(color.rgb,lettering.rgb,lettering.a * showLabel);
    color.a *= 1. - smoothstep(-fwidth(d), 0., d);
  `,
};

// Position-based spring surface for the visible 9-by-7 patch. Restoring anchors
// hold the material on the sphere. Shared edge nodes carry disturbances between tiles.
export function createGlassSurface(columns, rows) {
  const stride = columns + 1;
  const size = stride * (rows + 1);
  const rest = new Float32Array(size * 3);
  for (let i = 0; i < size; i++) {
    rest[3*i] = (i % stride - columns/2) * .5;
    rest[3*i+1] = (Math.floor(i/stride) - rows/2) * .37;
  }
  const current = rest.slice(), previous = rest.slice();
  const links = [];
  function connect(i,j,compliance) {
    const length = Math.hypot(rest[3*i]-rest[3*j],rest[3*i+1]-rest[3*j+1]);
    links.push({a:i*3,b:j*3,length,compliance,lambda:0});
  }
  for(let y=0;y<=rows;y++) for(let x=0;x<=columns;x++){
    const i=y*stride+x;
    if(x)connect(i,i-1,.00005);
    if(y)connect(i,i-stride,.00005);
    if(x&&y)connect(i,i-stride-1,.00012);
    if(x<columns&&y)connect(i,i-stride+1,.00012);
    if(x>1)connect(i,i-2,.001);
    if(y>1)connect(i,i-2*stride,.001);
  }
  let remainder=0;
  return {
    advance(dt, vx, vy, pointerX, pointerY, aspect) {
      const h=1/90;
      remainder+=Math.min(dt,.06);
      while(remainder>=h){
        remainder-=h;
        for(let i=0;i<size;i++){
          const k=i*3;
          const dx=rest[k]-(pointerX-.5)*aspect;
          const dy=rest[k+1]-(pointerY-.5);
          const influence=Math.exp(-1.8*(dx*dx+dy*dy));
          const forceX=-vx*(.15+influence)*2;
          const forceY=-vy*(.15+influence)*2;
          const forceZ=(vx*dx+vy*dy)*influence*8;
          for(let j=0;j<3;j++){
            const value=current[k+j],speed=(value-previous[k+j])*.962;
            previous[k+j]=value;
            const pull=(rest[k+j]-value)*69;
            current[k+j]=value+speed+(pull+(j===0?forceX:j===1?forceY:forceZ))*h*h;
          }
        }
        for(const edge of links)edge.lambda=0;
        for(let pass=0;pass<3;pass++) for(const edge of links){
          const {a,b,length,compliance}=edge;
          const dx=current[a]-current[b],dy=current[a+1]-current[b+1],dz=current[a+2]-current[b+2];
          const dist=Math.max(.0001,Math.hypot(dx,dy,dz));
          const alpha=compliance/(h*h);
          const delta=(-(dist-length)-alpha*edge.lambda)/(2+alpha);
          edge.lambda+=delta;
          const f=delta/dist;
          current[a]+=dx*f;current[a+1]+=dy*f;current[a+2]+=dz*f;
          current[b]-=dx*f;current[b+1]-=dy*f;current[b+2]-=dz*f;
        }
      }
    },
    corners(slot, vectors) {
      const bottom=slot%columns+Math.floor(slot/columns)*stride;
      for(let j=0;j<4;j++){
        const k=(bottom+(j%2)+(j>=2?stride:0))*3;
        vectors[j].set(current[k]-rest[k],current[k+1]-rest[k+1],current[k+2]-rest[k+2]);
      }
    },
  };
}
